CustomField.formula:
/*If close date is in the future, use close date*/
if( IsNull(Close_Date_Actual__c)=false ,   Close_Date_Actual__c ,
if( CloseDate>=Today(), CloseDate,  

/*else if close date is passed, but before 25h*/
if(Day(Today())<=25,

/*Current Month 25th*/
DateValue(Text(Year(Today()))&"-"&Text(MONTH(Today()))&"-25"),

/*else if next month*/
/*Next Month 25th*/
DateValue(Text(if(MONTH(TODAY())=12, Year(Today())+1, Year(Today())))&"-"&Text(if(MONTH(TODAY())=12, 1, MONTH(Today())+1))&"-25")
)
)
)
